style.css:
@-moz-document domain("youtube.com") {
/* Background color */
  body, ytd-app {
    background-color: #4D4D4D !important; /* Dark background */
    color: #9C9C9C !important; /* Default text color */
    font-family: 'Comic Sans MS', cursive, sans-serif !important; /* Custom font */
  }

  /* Change font and font color of titles */
  h1, h2, h3, h4, h5, h6, .title, .ytd-video-primary-info-renderer {
    font-family: 'Comic Sans MS', cursive, sans-serif !important;
    color: #00ff00 !important; /* Neon green titles */
  }

  /* Change font and color of video descriptions and other texts */
  #description, .content, yt-formatted-string, .ytd-video-secondary-info-renderer, span {
    font-family: 'Comic Sans MS', cursive, sans-serif !important;
    color: #008000 !important; /* Light grey descriptions */
  }

  /* Sidebar and video list background */
  ytd-mini-guide-renderer, ytd-guide-renderer, ytd-item-section-renderer {
    background-color: #090055 !important; /* Even darker sidebar */
  }

  /* Buttons (like, subscribe, etc.) */
  tp-yt-paper-button, ytd-subscribe-button-renderer {
    background-color: #9E00FF !important; /* Red buttons */
    color: #ffffff !important;
    font-family: 'Comic Sans MS', cursive, sans-serif !important;
  }

  /* Search bar */
  input#search {
    background-color: #007F00 !important;
    color: #ffffff !important;
    font-family: 'Comic Sans MS', cursive, sans-serif !important;
  }
}
